@Test(timeout = 60000)
public void test() throws Exception {
    featureService.installFeature("scr");
    featureService.installFeature("http");
    Bundle bundle = bundleContext.installBundle("mvn:org.apache.karaf.examples/karaf-websocket-example/" + System.getProperty("karaf.version"));
    bundle.start();
    String httpList = executeCommand("http:list");
    while (!httpList.contains("Deployed")) {
        Thread.sleep(1000);
        httpList = executeCommand("http:list");
    }
    System.out.println(httpList);
    WebSocketClient client = new WebSocketClient();
    SimpleSocket socket = new SimpleSocket();
    client.start();
    URI uri = new URI("ws://localhost:" + getHttpPort() + "/example-websocket");
    ClientUpgradeRequest request = new ClientUpgradeRequest();
    client.connect(socket, uri, request);
    socket.awaitClose(10, TimeUnit.SECONDS);
    assertTrue(socket.messages.size() > 0);
    assertEquals("Hello World", socket.messages.get(0));
    client.stop();
}

@Test
public void externalConfigTest() throws Exception {
    Path dir = Paths.get(System.getProperty("karaf.base"), "system/org/foo/bar/1.0-SNAPSHOT");
    Files.createDirectories(dir);
    //
    writeTo(//
    dir.resolve("bar-1.0-SNAPSHOT.properties"), "key=value");
    //
    writeTo(//
    dir.resolve("bar-1.0-SNAPSHOT-features.xml"), "<features name='org.foo'>\n" + "  <feature name='bar' version='1.0-SNAPSHOT'>\n" + "    <config name='org.foo' external='true'>\n" + "      mvn:org.foo/bar/1.0-SNAPSHOT/properties" + "    </config>\n" + "  </feature>\n" + "</features>\n");
    Configuration[] cfgs = configurationAdmin.listConfigurations("(service.pid=org.foo)");
    assertNull(cfgs);
    featureService.addRepository(URI.create("mvn:org.foo/bar/1.0-SNAPSHOT/xml/features"), true);
    cfgs = configurationAdmin.listConfigurations("(service.pid=org.foo)");
    assertNotNull(cfgs);
    assertEquals(1, cfgs.length);
    assertEquals("value", cfgs[0].getProcessedProperties(null).get("key"));
}

