@Test
public void testMBean() throws Exception {
    System.out.println("== Installing ActiveMQ");
    featureService.installFeature("aries-blueprint");
    featureService.installFeature("activemq-broker-noweb");
    System.out.println("== Installing JMS feature");
    featureService.installFeature("jms");
    featureService.installFeature("pax-jms-activemq");
    Thread.sleep(2000);
    MBeanServer mBeanServer = ManagementFactory.getPlatformMBeanServer();
    ObjectName objectName = new ObjectName("org.apache.karaf:type=jms,name=root");
    mBeanServer.invoke(objectName, "create", new String[] { "testMBean", "activemq", "tcp://localhost:61616", "karaf", "karaf", "transx" }, new String[] { "java.lang.String", "java.lang.String", "java.lang.String", "java.lang.String", "java.lang.String", "java.lang.String" });
    Thread.sleep(2000);
    mBeanServer.invoke(objectName, "send", new String[] { "jms/testMBean", "queueMBean", "message", null, "karaf", "karaf" }, new String[] { "java.lang.String", "java.lang.String", "java.lang.String", "java.lang.String", "java.lang.String", "java.lang.String" });
    Integer count = (Integer) mBeanServer.invoke(objectName, "count", new String[] { "jms/testMBean", "queueMBean", "karaf", "karaf" }, new String[] { "java.lang.String", "java.lang.String", "java.lang.String", "java.lang.String" });
